INSERT INTO `shop_category` VALUES (184,'CRONUS AG','B2C-DEMO','DEU',10000,0,1,1,'Golfausstattung',0,'golf',0,0,0,4,0,1,0,1,'','','<h1>Golfausstattung</h1>\r\n<img alt=\"\" src=\"https://2017.dc-test.de/userdata/images/Kategoriebilder/Cronus-Golf_Kategoriebild_Golfausstattung.jpg\" style=\"width: 1016px; height: 149px; margin-top: 10px;\" /><br />\r\n<br />\r\nVom Driver f&uuml;r die perfekte Weite &uuml;ber den Putter f&uuml;r&#39;s Pr&auml;zisionsspiel, den Eisensatz f&uuml;r die individuellen Anspr&uuml;che, den Ball mit dem richtigen Spin bis hin zu Bags und Trolleys zum Verstauen und Transportieren&nbsp;deines&nbsp;Equipment&nbsp;- hier findest du tolle Angebote auf Golfausstattung von Top-Herstellern wie TaylorMade, Ping, Callaway, Tileist, Mizuno und mehr.','Das A und O f&uuml;r ein erfolgreiches Golfspiel ist die Sorgfalt bei der Auswahl der Golfausstattung. So sollten Sie sich beim Kauf von Golfschl&auml;gern, ganz gleich ob Sie sich f&uuml;r einen Driver von Callaway, einem Fairwayholz von Cleveland, einem Wedge von Mizuno oder einem Golf Putter von Odyssey, entscheiden, nicht allein auf die Optik verlassen, sondern einen Golfschl&auml;ger w&auml;hlen, der zu Ihrem pers&ouml;nlichen Spielverhalten passt. Um sich den Herausforderungen des Golfsport zu stellen, geh&ouml;ren aber auch komfortable Golfschuhe, praktisches und materialschonendes Zubeh&ouml;r wie Golftaschen und Golf Trolleys, die f&uuml;r dauerhafte Spielfreude sorgen und Sie bei Ihren sportlichen Zielen unterst&uuml;tzen. Da Golfer und Golferinnen viele Kilometer auf den Fairways dieser Welt zur&uuml;cklegen, sollte der Blick auch auf die Anforderungen an gute und bequeme Golf Schuhe gerichtet sein. Hierzu z&auml;hlen Komfort, Funktionalit&auml;t, Standfestigkeit und nat&uuml;rlich modische Aspekte. Eine gro&szlig;e Rolle spielen auf dem Golfplatz Golf Trolleys, entweder als Push- oder Pull-Trolleys oder als Elektro-Trolleys. Zu den Top-Marken geh&ouml;ren etwa Bag Boy, Big Max und TiCad, die eine leichte Bedienbarkeit und komfortable Laufeigenschaften dem Golfer oder der Golferin bieten. Dabei flie&szlig;en sowohl aktuelle Trends als auch neue, fortschrittliche Material- und Fertigungstechnologien mit ein.',1,NULL,NULL,0,NULL,NULL,0,'','','','','',0,0,'/golf/','','','','','',0,0,0),(185,'CRONUS AG','B2C-DEMO','DEU',20000,10000,1,2,'Golfschläger',10000,'golfschlaeger',0,0,0,8,0,1,0,1,'','golfschlaeger_satz_tour_classic_tc_24_herren.jpg','<h1>Golfschl&auml;ger</h1>\r\n','',1,NULL,NULL,0,NULL,NULL,0,'','','','','',0,0,'/golf/golfschlaeger/','','','','','',336,0,1),(186,'CRONUS AG','B2C-DEMO','DEU',30000,20000,1,3,'Hybriden',10000,'hybriden',0,0,0,0,2,1,0,0,'','taylormade-m2-hybrid.jpg','','',1,NULL,NULL,0,NULL,NULL,0,'','','','','',0,0,'/golf/golfschlaeger/hybriden/','','','','','',0,0,0),(187,'CRONUS AG','B2C-DEMO','DEU',40000,20000,2,3,'Driver',10000,'driver',0,0,0,8,2,1,4,0,'','ab-driver_3_42.jpg','<h1>Driver</h1>\r\n','',1,NULL,NULL,0,NULL,NULL,0,'','','','','',0,0,'/golf/golfschlaeger/driver/','','','','','',0,0,0),(188,'CRONUS AG','B2C-DEMO','DEU',50000,20000,3,3,'Eisen',10000,'eisen',0,0,0,0,2,1,0,0,'','callaway-big-bertha-eisen-2015.jpg','','',1,NULL,NULL,0,NULL,NULL,0,'','','','','',0,0,'/golf/golfschlaeger/eisen/','','','','','',0,0,0),(189,'CRONUS AG','B2C-DEMO','DEU',60000,20000,4,3,'Putter',10000,'putter',0,0,0,0,2,1,0,0,'','wgw889034-visor-putter-face.jpg','','',1,NULL,NULL,0,NULL,NULL,0,'','','','','',0,0,'/golf/golfschlaeger/putter/','','','','','',0,0,0),(190,'CRONUS AG','B2C-DEMO','DEU',70000,20000,5,3,'Komplettsets',10000,'komplettsets',0,0,0,0,2,1,0,0,'','hdx-halbsatz-herren.jpg','','',1,NULL,NULL,0,NULL,NULL,0,'','','','','',0,0,'/golf/golfschlaeger/komplettsets/','','','','','',0,0,0),(191,'CRONUS AG','B2C-DEMO','DEU',80000,20000,6,3,'Kinder/Jugendschläger',10000,'kinder-jugen',0,0,0,0,2,1,0,0,'','wilson-pro-staff-hdx-junior-komplettset-5-8.jpg','','',1,NULL,NULL,0,NULL,NULL,0,'','','','','',0,0,'/golf/golfschlaeger/kinder-jugen/','','