INSERT INTO `shop_text_module` VALUES (1,'CRONUS AG','B2C-DEMO-MAIL1-DEU','Thank you for shopping with us | ','<table style=\"background: rgb(153, 193, 55); color: rgb(255, 255, 255);\">\r\n	<tbody>\r\n		<tr>\r\n			<td width=\"20\"><font face=\"Arial,MS Sans Serif\" size=\"2\">&nbsp;</font></td>\r\n			<td height=\"125\" style=\"text-align: center;\" width=\"225\"><font face=\"Arial,MS Sans Serif\" size=\"2\"><img height=\"80\" src=\"https://2017.dc-test.de/userdata/images/CRONUS-Golf_Logo.png\" style=\"vertical-align: middle;\" width=\"195\" /></font></td>\r\n			<td style=\"text-align: center;\" width=\"155\"><font face=\"Arial,MS Sans Serif\" size=\"2\"><strong><a href=\"https://2017.dc-test.de/b2c/de/shop/golf/\" style=\"color: rgb(255, 255, 255); text-decoration: none;\">GOLFAUSSTATTUNG</a></strong></font></td>\r\n			<td style=\"text-align: center;\" width=\"85\"><font face=\"Arial,MS Sans Serif\" size=\"2\"><strong><a href=\"https://2017.dc-test.de/b2c/de/shop/fashion/\" style=\"color: rgb(255, 255, 255); text-decoration: none;\">FASHION</a></strong></font></td>\r\n			<td style=\"text-align: center;\" width=\"135\"><font face=\"Arial,MS Sans Serif\" size=\"2\"><strong><a href=\"https://2017.dc-test.de/b2c/de/shop/geschenkideen/\" style=\"color: rgb(255, 255, 255); text-decoration: none;\">GESCHENKIDEEN</a></strong></font></td>\r\n			<td style=\"text-align: center;\" width=\"90\"><font face=\"Arial,MS Sans Serif\" size=\"2\"><strong><a href=\"https://2017.dc-test.de/b2c/de/shop/aktionen/\" style=\"color: rgb(255, 255, 255); text-decoration: none;\">AKTIONEN</a></strong></font></td>\r\n			<td style=\"text-align: center;\" width=\"90\"><font face=\"Arial,MS Sans Serif\" size=\"2\"><strong><a href=\"https://2017.dc-test.de/b2c/de/shop/marken/\" style=\"color: rgb(255, 255, 255); text-decoration: none;\">MARKEN</a></strong></font></td>\r\n			<td width=\"20\"><font face=\"Arial,MS Sans Serif\" size=\"2\">&nbsp;</font></td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<table>\r\n	<tbody>\r\n		<tr>\r\n			<td width=\"20\">&nbsp;</td>\r\n			<td width=\"800\"><br />\r\n			<font face=\"Arial,MS Sans Serif\" size=\"3\"><strong>Lieber Kunde,</strong> </font>\r\n			<p><font face=\"Arial,MS Sans Serif\" size=\"3\">vielen Dank f&uuml;r&nbsp;Ihr Vertrauen!&nbsp;Ihre Bestellung wurde unter der Nummer <strong>%order_no%</strong> erfasst und wird in K&uuml;rze von uns weiter bearbeitet.</font></p>\r\n\r\n			<p><font face=\"Arial,MS Sans Serif\" size=\"3\">Hier die Aufstellung der Bestellung:<br />\r\n			<br />\r\n			<br />\r\n			%order_lines%<br />\r\n			<br />\r\n			<br />\r\n			Weiterhin viel Spa&szlig; beim Einkaufen w&uuml;nscht</font></p>\r\n\r\n			<p><font face=\"Arial,MS Sans Serif\" size=\"3\"><strong>Dein Cronus Golf-Team</strong></font><br />\r\n			&nbsp;</p>\r\n			</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<table style=\"background: rgb(153, 193, 55); color: rgb(255, 255, 255);\">\r\n	<tbody>\r\n		<tr style=\"background: rgb(153, 193, 55); color: rgb(255, 255, 255);\">\r\n			<td height=\"125\" width=\"20\"><font face=\"Arial,MS Sans Serif\" size=\"2\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</font></td>\r\n			<td style=\"padding: 10px; color: rgb(255, 255, 255);\" width=\"200\">\r\n			<p><font face=\"Arial,MS Sans Serif\" size=\"2\"><strong><font face=\"Arial,MS Sans Serif\" size=\"2\">CRONUS GOLF</font></strong></font><br />\r\n			<br />\r\n			<font face=\"Arial,MS Sans Serif\" size=\"2\">Ihr Online-Golfshop<br />\r\n			F&uuml;rstenriederstra&szlig;e 61<br />\r\n			80686 M&uuml;nchen</font></p>\r\n			</td>\r\n			<td style=\"padding: 10px; color: rgb(255, 255, 255);\" width=\"200\"><font face=\"Arial,MS Sans Serif\" size=\"2\">Tel: 089 / 829925-0<br />\r\n			Fax: 089 / 829925-50<br />\r\n			<br />\r\n			<a href=\"mailto:info@cronus-ag.de\">info@cronus-ag.de</a><br />\r\n			www.cronus-golf.de</font></td>\r\n			<td style=\"padding: 10px; color: rgb(255, 255, 255);\" width=\"200\"><font face=\"Arial,MS Sans Serif\" size=\"2\">Gesch&auml;ftsf