INSERT INTO `solr_materialized` VALUES (1,'CRONUS AG','B2C-DEMO','','DEU','DEU','70061','70061',1,'MP 650 Driver Herren','','MP 650 Driver Herren','Mizuno',299.0000,299.0000,0.00,1,NULL,NULL,NULL,NULL,'/golf/golfschlaeger/driver/MP+650+Driver+Herren/',0.00,'5_mp650face.jpg','70062~|~70063~|~70064~|~70088~|~70128~|~70131~|~70137~|~70138~|~70139~|~70153~|~70206~|~70244','0000-00-00T00:00:00Z','9999-12-31T23:59:59Z',NULL,'Technische Daten <h1>Technische Daten</h1>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<ul>\r\n	<li><strong>Tourerprobter Schl&auml;gerkopf:</strong></li>\r\n</ul>\r\n\r\n<p style=\"margin-left: 80px\">Klassische Kopfform mit &quot;Deep-Face&quot; f&uuml;r erh&ouml;hte Kontrollierbarkeit</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<ul>\r\n	<li><strong>Neue geschmiedete Titan-Schlagfl&auml;che:</strong></li>\r\n</ul>\r\n\r\n<p style=\"margin-left: 80px\">Design mit 3 verschiedenen Dicken f&uuml;r hohen Energietransfer (COR)</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<ul>\r\n	<li><strong>6-teiliger Titan-Schl&auml;gerkopf:</strong></li>\r\n</ul>\r\n\r\n<p style=\"margin-left: 80px\">erlaubt einen Gewichtsspielraum von 18 Gramm f&uuml;r optimalen COG/MOI</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<ul>\r\n	<li><strong>Ultrad&uuml;nne 0,5-mm-Krone:</strong></li>\r\n</ul>\r\n\r\n<p style=\"margin-left: 80px\">niedriger Schwerpunkt f&uuml;r hohen Ballflug und wenig Spin</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<ul>\r\n	<li><strong>Harmonischer Impact-Sound:</strong></li>\r\n</ul>\r\n\r\n<p style=\"margin-left: 80px\">spezielle Soundtechnologie f&uuml;r einen satten, &uuml;berzeugenden Klang im Treffmoment</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<ul>\r\n	<li><strong>Feste Innengewichte:</strong></li>\r\n</ul>\r\n\r\n<p style=\"margin-left: 80px\">Doppelgewichte f&uuml;r einen hohen Ballflug und wenig Spin</p>\r\n~|~Kurzbeschreibung <p>&Uuml;berraschen Sie Ihre Mitspieler mit einer Tasche aus der limitierten Serie. Jede Saison ein neues Design zum Sammeln.</p>\r\n~|~Beschreibung <p>Ausstattungsdetails&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;Vorteil<br />\r\nMizuno Kabuki&trade; Top-Cuff.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;Patentiertes Organisationssystem mit &bdquo;Divide and Slide&bdquo;-Technologie<br />\r\nMizuno AeroStrap&trade;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Leichter, vorgeformter zweifacher Schultergurt mit Dreifachpolsterung.<br />\r\nMizuno Cable Grip&trade;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;Leichter, flexibler Griff mit Soft-Touch-Ummantelung<br />\r\nMizuno AirFlow Hippad&trade;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;Mizuno Airmesh&trade; H&uuml;ftpolster reduziert die Schwei&szlig;bildung beim Tragen.<br />\r\nMizuno Shower Cap&trade;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Leichte, kompakte Regenhaube mit Druckknopfbefestigung.</p>\r\n~|~Spezifikationen <p>Ma&szlig;e&nbsp; 34.5&quot; Height<br />\r\n8.5&quot; Width<br />\r\nGewicht&nbsp; 2.3kg<br />\r\nKategorie&nbsp; Carry/Stand</p>\r\n~|~Technische Daten <h1>Technische Daten</h1>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<ul>\r\n	<li><strong>Tourerprobter Schl&auml;gerkopf:</strong></li>\r\n</ul>\r\n\r\n<p style=\"margin-left: 80px\">Klassische Kopfform mit &quot;Deep-Face&quot; f&uuml;r erh&ouml;hte Kontrollierbarkeit</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<ul>\r\n	<li><strong>Neue geschmiedete Titan-Schlagfl&auml;che:</strong></li>\r\n</ul>\r\n\r\n<p style=\"margin-left: 80px\">Design mit 3 verschiedenen Dicken f&uuml;r hohen Energietransfer (COR)</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<ul>\r\n	<li><strong>6-teiliger Titan-Schl&auml;gerkopf:</strong></li>\r\n</ul>\r\n\r\n<p style=